    ["Boss frames normally appear only during boss encounters. Enable Boss Frames and use Edit Mode or Boss Preview to test them outside combat."] = "Boss 框架通常只會在遇到 Boss 時出現。啟用 Boss 框架並使用編輯模式或 Boss 預覽在戰鬥外測試它們。",
