    ["Opens: Group Frames > Health & Text > Range Fade"] = "開啟：群組框架 > 健康與文字 > 範圍淡入淡出",
    ["Opens: Group Frames > Indicators"] = "開啟：群組框架 > 指標",
    ["Opens: Group Frames > Indicators > Dispel / Status Icons"] = "開啟：群組框架 > 指示器 > 消除/狀態圖示",
    ["Opens: Group Frames > Indicators > Status Icons"] = "開啟：群組框架 > 指示器 > 狀態圖示",
    ["Opens: Group Frames > Layout"] = "開啟：群組框架 > 佈局",
    ["Opens: Group Frames > Layout / Buffs & Debuffs / Indicators"] = "開啟：群組框架 > 佈局/增益和減益/指示器",
    ["Opens: Group Frames > Layout > Anchoring"] = "開啟：群組框架 > 佈局 > 錨定",
