    ["Opens: Group Frames > Layout > Smooth health fill"] = "開啟：群組框架 > 佈局 > 平滑健康填充",
    ["Opens: Modules > Style"] = "開啟：模組 > 樣式",
    ["Opens: Player > Castbar"] = "開啟：播放器 > Castbar",
    ["Opens: Player > Frame Basics"] = "開啟：播放器 > 框架基礎知識",
    ["Opens: Player > Frame Basics > Smooth fill"] = "開啟：播放器 > 框架基礎 > 平滑填充",
    ["Opens: Player > Load Conditions"] = "開啟：播放器 > 負載條件",
    ["Opens: Player > Portrait"] = "開啟：播放器 > 肖像",
    ["Opens: Player > Status icons > Indicator: Level"] = "開啟：播放器 > 狀態圖示 > 指示器：等級",
    ["Opens: Player > Text"] = "開啟：播放器 > 文字",
    ["Opens: Player > Transparency"] = "開啟：播放器 > 透明度",
    ["Opens: Profiles > Export / Import"] = "開啟：設定檔 > 匯出/匯入",
    ["Opens: Profiles > Profile Management / Export / Import"] = "開啟：設定檔 > 設定檔管理/匯出/匯入",
    ["Opens: Target of Target > Frame Basics"] = "開啟：目標的目標 > 框架基礎知識",
    ["Opens: Unit Auras > Aura Filters & Sorting"] = "開啟：單位光環 > 光環過濾器和排序",
    ["Opens: Unit Auras > Caps & Icons"] = "開啟：單位光環 > 上限和圖標",
    ["Opens: Unit Auras > Display"] = "開啟：單位光環 > 顯示",
    ["Opens: Unit Auras > Player > Custom caps > Caps & Icons > Max Buffs"] = "開啟：單位光環 > 玩家 > 自訂上限 > 上限和圖示 > 最大增益",
    ["Opens: Unit Auras > Text Coloring"] = "開啟：單位光環 > 文字著色",
    ["Padding"] = "填充",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "隊伍、Raid 和 Mythic Raid 組框架佈局、長條圖、光環、指示器、範圍覆蓋和位置",
    ["Position"] = "職位",
    ["Positions class bar ABOVE Essential Cooldowns"] = "將等級欄置於基本冷卻之上",
    ["Preserve HP color on all unit frames"] = "在所有單元框架上保留 HP 顏色",
    ["Press Ctrl+C to copy:"] = "按Ctrl+C複製：",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "預覽遵循目前 Castbar 可見性、圖示、文字和全域顏色設定。",
    ["Profile actions"] = "設定檔操作",
    ["Quick Setup: Detached Class Bar"] = "快速設定：分離類別欄",
    ["Reload"] = "重新載入",
    ["Rows"] = "行數",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "與每個單元頁面相同的設定 > 透明度。它使用相同的 HP 軌道顏色；這裡的 off 表示至少有一個單元幀關閉。",
    ["Secret aura (name/fingerprint matched)"] = "秘密光環（名字/fingerprint匹配）",
    ["Select:"] = "選擇：",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "將欄背景色調設定為白色，並在深色模式下啟用自訂顏色。如果是黑色，請在所有單元框架上啟用保留 HP 顏色。",
    ["Setup Now"] = "立即設定",
    ["Slot"] = "插槽",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "有些佈局變更會重建框架，而視覺變更會立即套用。如果需要，請關閉並重新開啟選單或在大型設定檔 /import 變更後重新載入。",
    ["Syncs & anchors power bar to class resources"] = "將功率條同步並錨定到班級資源",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "使用中的檔案會依角色分別儲存。新角色會使用此檔案，而非 Default。",
    ["This layer is off in settings and cannot be shown in preview."] = "此圖層在設定中處於關閉狀態，無法在預覽中顯示。",
    ["Type a name here before creating or copying a profile."] = "在建立或複製設定檔之前，請在此處鍵入名稱。",
    ["Undo"] = "撤銷",
    ["Unit Frame Preview"] = "單位框架預覽",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "單元框架狀態圖示位於每個單元頁面上。群組框架指示器位於群組框架 > 指示器中。",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "使用/msuf開啟MSUF2。儀表板還包含重置、支援、設定檔和縮放工具。",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "使用儀表板 > 重設框架移動器的位置。僅當您想要重設、複製、匯入或取代設定檔資料時才使用設定檔。",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "使用「全域樣式」>「條」來反白邊框，使用「群組框架」>「角色」、「威脅」、「驅散」、「咒語」、「角落」和「突襲標記」指示器。",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "使用「群組框架」>「佈局」來調整大小和間距，使用「增益」和「減益」來調整光環雜亂，使用「指示器」來調整固定位置狀態圖示。",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "使用群組框架頁面：尺寸佈局/growth/sorting，條形的健康和文字/text，光環的增益和減益以及狀態圖示的指示器。",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "使用 MSUF 編輯模式拖曳單一單元框。當您需要精確的錨定目標或 X/Y 值時，請使用單位頁面 > 錨定。",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "使用 MSUF 編輯模式拖曳支援的演員條。每個單元頁面上都有每個單元的castbar啟用/icon/text選項；共享castbar樣式位於全域樣式> Castbar。",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "使用MSUF編輯模式拖曳播放器框架。若要獲得精確的錨點或 X/Y 值，請隨後開啟「播放器」>「錨定」。",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "使用儀表板比例控制進行選單比例或 UI 比例。您也可以從 MSUF2 視窗的一角調整其大小。",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "使用單元頁面進行每個單元的 Castbar 切換，使用全域樣式 > Castbar 進行共享紋理、方向、GCD、文字和中斷選項。",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "如果 HP 條褪色使空的生命值區域消失或看起來黑色，請使用此選項。它與顏色保持相同的 HP 軌道顏色。",
    ["Value:"] = "價值：",
    ["View"] = "查看",
    ["Welcome to Class Resources!"] = "歡迎來到課堂資源！",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW 會阻止戰鬥中一些受保護的幀變更。離開戰鬥，然後套用佈局、錨定、enable/disable、設定檔或受保護的框架變更。",
    ["bottom"] = "底部",
    ["change background color unit frames"] = "變更單位框架背景顏色",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "類別資源佈局、行為、樣式、自動隱藏、獨立電源欄和替代法力設置",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "點選要隱藏的圖層 - 拖曳預覽元素 - 箭頭微移所選內容",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "框架顏色、class/NPC 顏色、能量顏色、castbar 顏色、光環顏色和遊戲顏色設置",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "遊戲增強設置，例如戰鬥文字、十字準線和點擊投射行為",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "全域castbar行為、紋理、GCD、bosscastbar和中斷指示器設置",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "語言/menu行為、更新節奏、工具提示、Blizzard幀處理、小地圖圖示、聲音和範圍淡入淡出設置",
    ["none"] = "無",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "可選的 style/module 設置，例如 MSUF 樣式和下拉樣式",
    ["scope disabled"] = "範圍已停用",
    ["shared"] = "共享",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "共享條形紋理、漸變、圓角框架角、吸收顯示、輪廓、高亮邊框、功率平滑和所有每個單元 /group 條形覆蓋",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "共享字體系列、文字樣式、name/power 文字著色、名稱縮寫和所有單位 /group 字體覆蓋",
    ["the entire active profile"] = "整個活動設定檔",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_zhTW) do
    if L[k] == nil or L[k] == k then L[k] = v end
end

L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r 隊伍框架已重設為預設值。"
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r 保留 HP 顏色會使用「顏色」中的相同 HP 軌道顏色，但部分條材質可能看起來不同。"
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "點擊控制點選取 - 拖曳自訂圖層 - 方向鍵微調所選項目；Blizzard 已鎖定"
