L["Don't show again"] = "不再顯示"
L["Frame disabled"] = "框架已停用"
L["Growth Direction"] = "成長方向"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "保留 HP 顏色會在圖層淡出啟用時保留 HP 填滿顏色，並使用「顏色」中的相同 HP 軌道顏色分別繪製缺少的生命值。\n\n當 HP 條淡出導致空 HP 區域消失或變黑時，這會有所幫助。啟用此選項後，部分自訂材質仍可能顯得扁平、偏暗或不同。"
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "將 %s 重設為預設值？\n\n這會為目前設定檔重設 %s。預設值會從目前 MSUF 出廠設定檔讀取，因此未來的預設變更會自動使用。"
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "將 %s 重設為預設值？\n\n這會將整個目前設定檔「%s」重設為目前 MSUF 出廠預設值。該設定檔中的每個選單都會受到影響。"
L["Reset Scopes"] = "重設範圍"

