L["|cffffcc00MSUF:|r Then click: MSUF Menu > Advanced > Factory Reset (or type /reload)."] = "|cffffcc00MSUF：|r然後點擊：MSUF 選單 > 進階 > 恢復原廠設定（或輸入 /reload）。"
