L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "新增專注目標框架支援，涵蓋單位設定、編輯模式、選單預覽、複製目標、文字選項、圖示與執行時刷新。"
