L["Added new Menu2 search module and improved search/guidance text."] = "新增 Menu2 搜尋模組並改進搜尋/引導文字。"
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "新增用於開關與圓角/superellipse 視覺的 UI/媒體資源。"
L["Added raid group number display next to unit names."] = "在單位名稱旁新增團隊小隊編號顯示。"
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "為單位、隊伍、光環、指示器、條列與進階頁面新增重新設計的 Menu2 卡片版面。"
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "新增圓角框架，並為單位框架、隊伍框架、條列、高亮、覆蓋層、吸收與指示器提供按表面控制。"
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "為即時單位/隊伍框架與 Menu2 預覽新增圓角遮罩媒體。"
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "在 全域樣式 > 條列 下新增圓角材質控制，包含按表面開關、搜尋、本地化、預覽支援與重新載入提示。"
