L["EM_HELP_BTN"] = "? 說明"
L["EM_HELP_BTN_TIP"] = "從編輯模式章節開啟\n完整的 MSUF 引導設定。"
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r 切換 Essential Cooldown Manager 的全域錨點。|cff60a5ffAnchor|r 開啟錨點選擇器；懸停一個命名框架，按住 Ctrl 並左鍵點擊，即可將其作為全域錨點。選擇自訂錨點會關閉 CDM。"
L["EM_HELP_COPYTO"] = "在單位和施法條彈窗中，|cff60a5ffCopy To|r 會把目前彈窗的設定複製到另一個目標。單位框架複製會保留目標的位置和錨點設定；施法條複製會保留目標的 X/Y 偏移。"
L["EM_HELP_DRAG"] = "在移動器覆蓋層上按住滑鼠左鍵並拖曳。即時框架會跟隨移動器，覆蓋層下方的 X/Y 讀數顯示目前螢幕偏移。放開按鈕即可儲存位置。"
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r 會退出編輯模式並保留目前變更。進入戰鬥也會退出編輯模式。彈窗中按 Escape 會關閉/取消；HUD 的 Exit 按鈕是正常退出方式。"
L["EM_HELP_NUDGE"] = "方向鍵移動目前作用目標。優先順序為：選取的預覽控制點、開啟的施法條彈窗、開啟的光環彈窗、目前選取的單位框架。步長：1 像素，Shift = 5 像素，Ctrl = 10 像素，Alt = 目前網格步長。"
L["EM_HELP_OPACITY"] = "捲動 |cff60a5ffBG ##%|r 控制項只會改變編輯模式背景覆蓋層的不透明度。它不會改變單位框架透明度或已儲存的框架可見性。"
L["EM_HELP_POPUP"] = "左鍵點擊移動器但不拖曳，會開啟它的編輯彈窗。單位彈窗可編輯框架大小、位置、文字錨點、分離資源設定，以及複製到單位選項。施法條和光環移動器會開啟各自的專用彈窗。"
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r 會在編輯模式中為缺少的目標、專注、目標的目標、寵物、首領和施法條預覽切換佔位資料。|cff60a5ffAuras|r 會切換光環預覽圖示和光環移動器框。"
L["EM_HELP_SNAP"] = "網格是視覺輔助。左鍵點擊 |cff60a5ffGrid ##px|r 可開關網格線；捲動可改變間距。|cff60a5ffSnap|r 是獨立功能：啟用後，拖曳的移動器會吸附到螢幕中心或其他可見移動器的邊緣/中心，並顯示橘色輔助線。"
L["EM_HELP_TITLE"] = "編輯模式 - 快速參考"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r 和 |cff60a5ffRedo|r 會恢復拖曳、微調和彈窗編輯前記錄的最近編輯模式變更。|cff60a5ffCancel All|r 會要求確認，恢復進入編輯模式前的快照，然後退出。"
