L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "Blizzard 模式讓 WoW 放置所選光環類型。MSUF 自訂模式讓 MSUF 控制光環大小、成長、位置、過濾和樣式。MSUF 驅散高亮會保留 Blizzard 圖示，同時允許 MSUF 顯示驅散邊框、發光和覆蓋效果。"
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Blizzard 渲染器仍處於作用中，但此群組因使用 Blizzard 開關關閉而為 MSUF Custom。其他作用中的 Blizzard 光環類型仍可能顯示相符法術，因此可能出現重複。"
L["Bottom Fade"] = "底部淡出"
L["Button"] = "按鈕"
L["Can MSUF hide debuffs with a blacklist?"] = "MSUF 能用黑名單隱藏減益嗎？"
L["Checked categories hide MSUF custom buff icons only. Blizzard-rendered buffs bypass this list, so Skyfury or Earth Shield can still appear while Use Blizzard: Buffs is enabled."] = "勾選的分類只會隱藏 MSUF 自訂增益圖示。Blizzard 渲染的增益會略過此清單，因此在啟用使用 Blizzard：增益時，Skyfury 或 Earth Shield 仍可能顯示。"
L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "勾選的分類只會隱藏 MSUF 自訂減益圖示。啟用使用 Blizzard：減益時，Blizzard 渲染的減益會略過此清單。"
