L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."]="優先框架會將自動選取的坦克和手動釘選的隊員顯示在一條穩定的額外列中。在隊伍中繼承隊伍框架，在團隊中繼承目前團隊或傳奇團隊框架。必須啟用對應的基礎團隊框架。開啟 團隊框架 > 優先 來選擇顯示對象、設定滑鼠指向快捷鍵和放置額外列。"
