L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "跳過僅結束本次發布巡迴。每個設定在選單 2 中仍然可用。"
L["Custom Aura tracking on Unitframes"] = "Unitframes 上的自訂 Aura 跟踪"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "在玩家、目標、專注目標和首領框架上最多建立三條自訂欄位,填入精確的增益或減益 SpellID,並透過按職業整理的欄位在目標框架上追蹤自己的 DoT。"
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "您的 MSUF 框架可以充當帶有圖標、計時器、持續時間條和全框架色調、邊框、發光或脈衝效果的聚焦 WeakAura 式追蹤器。"
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "每個受支援的單位幀三個自訂光環追蹤器、精確的咒語白名單和全幀效果"
L["Build a Custom tracker"] = "建立自訂追蹤器"
L["Aura settings in the right place"] = "光環設定各歸其位"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "設定與個別樣式現在位於對應的單位框體與隊伍/團隊選單中。外觀 > 光環提供擴充的共用樣式。"
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "在對應選單中設定每個框體，再到光環選單統一設定圖示形狀、邊框、陰影、顏色與間距。"
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "每個框體的光環控制，以及外觀 > 光環中的擴充共用樣式"
L["Open shared Aura styles"] = "開啟共用光環樣式"
L["Adaptive Party and Raid layouts"] = "自適應派對和團隊佈局"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "隊伍、團隊和傳奇團隊獲得了自適應版面與縮放、每條欄位的光環篩選與黑名單、專屬的 Dispel Overlay 頁面,而且你可以按組別決定由 MSUF 還是暴雪繪製框架。"
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "一套團隊設定可以從五人本一路陪你進入團隊副本，而且你可以逐列決定哪些光環才允許顯示。"
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "自適應隊伍版面與縮放、隊伍光環篩選與黑名單、Dispel Overlay 頁面以及按組別的框架提供者設定"
L["Open Group Layout"] = "開放群組佈局"
L["New health values and text formats"] = "新的健康值和文字格式"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "生命值文字可以用更一致的格式顯示縮寫或完整數值,新的最大生命值損失覆蓋層會在單位和隊伍框架上標出被降低的最大生命值。"
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "您可以選擇緊湊的可讀性或精確的數字，而無需放棄已使用的佈局。"
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "新的生命值縮寫、完整數值、文字格式以及最大生命值損失覆蓋層"
L["Open HP Text Editor"] = "開啟生命值文字編輯器"
L["More flexible class resources"] = "更靈活的班級資源"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "類資源獲得了獨立的佈局、額外的形狀以及更精細的每槽和全狀態顏色。"
L["You can move class information where your eyes already are and make important states easier to read."] = "您可以將類別資訊移動到您的視線所在的位置，並使重要的狀態更易於閱讀。"
L["detached class resources, new shapes and per-state colors"] = "獨立的類別資源、新形狀和每個狀態的顏色"
L["Configure Class Resources"] = "配置類別資源"
L["Cast target text"] = "投射目標文本"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "目標、焦點和 Boss 施法欄現在可以透過專用的文字樣式顯示目前咒語的目標是誰。"
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "您可以識別重要演員的目的地，而無需將注意力從演員欄上移開。"
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "Target、Focus 和 Boss 框架上的投射目標名稱及其文字樣式"
L["Open Target Cast Bar"] = "打開目標投射欄"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "在使用首次載入操作之前，請查看或跳過儀表板上的發布亮點。"
L["Priority Frames for the units that matter"] = "為最重要的單位準備的優先框體"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "手動固定最多五名隊友，或讓 MSUF 自動挑選坦克，給他們一條專屬列，戰鬥中絕不重新排序。"
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "你必須盯著的人在畫面上始終占據同一個位置，並保留隊伍或團隊的外觀和點擊施法。"
L["Priority Frames, manual and automatic pinning, and their own placement"] = "優先框體、手動與自動固定，以及它們各自的位置"
L["Set up Priority Frames"] = "設定優先框體"
L["One Colors page with click-to-paint"] = "一個支援點擊上色的顏色頁面"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "所有顏色集中到一個頁面，分為玩家與目標、隊伍與團隊、施法條、光環、能量和職業資源等工作區，每個都有自己的即時預覽。"
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "你可以直接在預覽中點擊元素來上色，而不必尋找對應色塊，並能重複使用最近或已儲存調色盤中的任何顏色。"
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "重建的顏色頁面、點擊上色預覽、調色盤和新的取色器"
L["Open the Colors page"] = "開啟顏色頁面"
L["One 0-30 layer scale for everything"] = "統一的 0-30 層級刻度"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "文字、狀態圖示、光環、邊框、條描邊、團隊指示器和職業資源全部按同一套 0-30 層級刻度排序。"
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "你可以精確決定誰畫在誰前面，任意層級滑桿旁的層級總覽會一次顯示整個疊放順序。"
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "整個插件通用的 0-30 層級刻度和層級總覽"
L["MSUF Edit Mode, rebuilt"] = "重建的 MSUF 編輯模式"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "編輯模式獲得了可停駐的工具列、每個框體上重新設計的快捷彈窗，以及與選單中表現一致的復原和重做。"
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "你可以直接在畫面上移動、縮放和複製框體，並在不重新開啟選單的情況下撤回任何誤操作。"
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "重建的編輯模式工具列、快捷彈窗以及共用的復原和重做"
L["Start Edit Mode"] = "啟動編輯模式"
L["Spell Indicators on Group Frames"] = "隊伍框架上的 Spell Indicators"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "在小隊和團隊框架上以圖示、方塊、長條或數字追蹤選定的增益,支援自訂法術清單和角落指示器。"
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "你可以直接在框架上看到缺少或即將到期的外部減傷和關鍵增益,並獲得到期圖示發光、生命條強調和整框特效提示。"
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "帶自訂光環清單、角落指示器和到期警告的 Spell Indicators"
L["Open Spell Indicators"] = "開啟 Spell Indicators"
L["Fill Direction for Health and Power"] = "生命與資源的填滿方向"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "每個單位框架都可以讓生命和資源從左到右、從右到左、從下到上或從上到下填滿。"
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "垂直或鏡像的血條版面成為每個框架的獨立選項——目前沒有任何其他單位框架插件提供這項功能。"
