L["Portraits: attached, detached or overlay"] = "頭像:吸附、獨立或覆蓋"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "頭像可以吸附在框架上、自由放置,或作為覆蓋層繪製在生命條內,並擁有獨立尺寸、九點錨定、不透明度和可平移的縮放。"
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "矩形和浮水印式頭像成為可能,Relief 環和隨形狀變化的邊框可以修飾方形、圓形、圓角和菱形頭像。"
