L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "職責、隊長、團隊標記、就位確認等所有狀態圖示都可以按指示器在十二種內建樣式或自選圖示之間切換。"
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "狀態圖示終於可以搭配你的介面風格,而不是始終使用暴雪素材,外部圖示包也能透過 SharedMedia 註冊。"
