L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "跳過此個人步驟會使用中性指導，並使導航、搜尋、自動儲存、撤銷/Redo 和頁面重置無法解釋。"
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "跳幀放置會導致整個幀的移動、捕捉、輕推和安全退出行為無法解釋。"
