L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "跳過“目標”框架將不會檢查其佈局、文字、指示器和光環選項。"
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "跳過焦點框架不會對其佈局、文字、指示器和光環選項進行檢查。"
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "跳過寵物框架將不會對其佈局、文字、指示器和光環選項進行檢查。"
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "跳過目標的目標會保留其佈局、文字和可見性選項。"
