L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "跳過 Boss 框架將保留其共享佈局、文字、指示器和光環選項。"
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "跳過群組佈局不會對幀大小、增長、排序、縮放和錨定進行審查。"
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "跳過組欄會導致生命值、力量、文字、範圍和驅散呈現未經審查。"
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "跳過群體光環會使群體增益、減益和法術指示器行為不被審查。"
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "跳過條會留下全局紋理、吸收、輪廓、高光和電源行為而不受審查。"
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "跳過演員欄會使演員外觀、文字、授權演員和中斷提示未經審查。"
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "跳過顏色不會檢查框架、功率、光環、等級、文字和演員欄顏色。"
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "跳過字體不會對全域字體、文字樣式、顏色和名稱縮寫進行審查。"
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "跳過光環造型後，buff/debuff 的大小、冷卻時間、堆疊數、持續時間條和排序均未經審查。"
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "跳過雜項會導致語言、選單行為、啟動、工具提示和暴雪框架整合不被審查。"
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "跳過課堂資源會使課堂佈局、行為、風格、可見性和替代電源顯示不被審查。"
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "跳過遊戲玩法會導致戰鬥計時器、狀態行為、類別切換和戰鬥十字準線未經審查。"
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "跳過設定檔將不檢查設定檔管理、專業化分配和匯出/import 備份。"
L["Skipping the final review hides the summary, but does not change any setting."] = "跳過最終審核會隱藏摘要，但不會更改任何設定。"
