L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "當瞬發法術觸發公共冷卻時，顯示一條簡短的施法條。\n\n填充與時間文字由客戶端根據真實（急速加成後）的公共冷卻時長原生驅動，施法條運行期間插件沒有逐幀開銷。真正的施法、引導或蓄力施法始終優先。"
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "引導時在玩家施法欄上顯示刻度分隔符號。 \n\n受支援的法術使用其實際的刻度計數，包括受支援的天賦和通道持續時間變更。不受支援的通道保留五個均勻間隔的後備線。自訂通道刻度設定會覆蓋自動佈局。 \n\n標記是事件驅動的，不會增加重複通道輪詢。"
L["Class Color (Reaction fallback)"] = "類別顏色（反應後備）"
L["Ready color (kick available)"] = "就緒顏色（可踢）"
L["Not ready color (kick on cooldown)"] = "未準備好顏色（啟動冷卻）"
L["PvP Flag (War Mode/PvP)"] = "PvP 旗幟（戰爭模式/PvP）"
L["Abbreviate HP values (K/M)"] = "縮寫 HP 值 (K/M)"
L["For specializations that use mana alongside another resource."] = "適用於與其他資源一起使用法力的專精。"
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "平滑資源變化。符文、精華充能和計時器保持自己的動畫。"
L["Exact Spell IDs are used when Blizzard exposes them."] = "當暴雪公開它們時，會使用精確的法術 ID。"
