L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "開啟「群組框架」>「光環」以取得增益/減益濾鏡、清單、可見度和版面配置。對於文字、冷卻時間、堆疊和持續時間條，請使用「外觀」>「光環」並選擇「派對」或「團隊」範圍。"
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "開啟群組框架 > 佈局。文字、資源欄和範圍淡入淡出排列在框架基礎和透明度旁邊。驅散疊加和減益條紋位於驅散疊加頁面。修復預測位於「全域樣式」>「條形」>「吸收顯示」中。"
L["Open it and choose a different value."] = "打開它並選擇不同的值。"
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "開啟受影響的 UnitFrame > Auras > Debuffs 並啟用本機 Dispellable 規則。對於派對/突襲，請使用“群組框架”>“光環”>“減益效果”。"
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "打開受影響的 UnitFrame > Auras > Debuffs 並使用其特定於框架的 SpellID 黑名單。群組排除直接位於群組框架 > 光環 > 減益中。"
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "開啟受影響的 UnitFrame > Auras 並選擇 Buffs 或 Debuffs。檢查其特定於框架的暴雪過濾器、黑名單、啟用狀態和圖標帽。對於派對/突襲，請使用“群組框架”>“光環”。"
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "打開受影響的 UnitFrame > Auras 以了解可見性、佈局、過濾器和黑名單。使用「外觀」>「光環」來實現範圍感知冷卻時間、堆疊、持續時間欄和圖示樣式。"
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "打開框架並展開光環。 Buffs 和 Debuffs 包含自己的暴雪過濾器和黑名單；自訂 1-3 包含自己的白名單。沒有單獨的“過濾器”選項卡。"
L["Open the matching color section below."] = "打開下面的匹配顏色部分。"
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "開啟此框架的淺黃色樣式。拼字選擇、位置、大小、圖層和框架突出顯示對於該指示器來說是唯一的。"
