L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "優先框架可以自動選擇治療者、DPS、職業或規格嗎？"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "優先幀可以自動顯示增強誘發器嗎？"
L["Can Priority Frames show my co-tank?"] = "優先幀可以顯示我的副坦克嗎？"
L["Can Priority Frames update during combat?"] = "優先幀可以在戰鬥中更新嗎？"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "檢查優先框架是否已啟用、您是否已分組、以及匹配的基礎派對或團隊框架是否已啟用。確認指定的坦克或手動固定的玩家目前位於該組中且可見插槽未滿。保存的缺席玩家不會創建空的佔位符，並且在戰鬥結束後在戰鬥結束時進行受保護的名單更改。"
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "類別顏色和健康梯度是運行時顏色，而不是單一可編輯的樣本。"
L["Cleave Training Dummy"] = "劈砍訓練假人"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "自訂 1-3 始終按幀儲存。此處的圖示樣式和全畫面效果僅變化"
L["Disabled or whitelist empty"] = "已停用或白名單為空"
L["Do Priority Frame pins persist, and what order do they use?"] = "優先幀引腳是否持續存在？它們使用什麼順序？"
L["Do Priority Frames inherit click casting and appearance?"] = "優先框架是否繼承點擊投射和外觀？"
L["Do Priority Frames use polling?"] = "優先權幀是否使用輪詢？"
L["Do Priority Frames work in parties and dungeons?"] = "優先框架在隊伍和地下城中有效嗎？"
L["Enter text"] = "輸入文字"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "現有的優先權框架在戰鬥中仍然可用，但魔獸世界保護安全的群組框架成員資格和佈局變更。任何需要安全刷新的引腳、名單、位置或位置變更都會在戰鬥結束後套用。在戰鬥之外更改優先幀鍵綁定。"
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "遵循 Unitframe 全域著色。樣本預覽目前的全域條形顏色。"
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "對於優先框架，佈局是整個設定檔範圍的，而引腳是特定於字元的。可見插槽可以設定為 1 到 5 個。首先自動填充水箱，然後按儲存的順序手動填充；重複的選擇出現一次。缺席的已儲存玩家會等待該玩家重新加入目前群組。"
L["How do I pin or unpin a player in Priority Frames?"] = "如何在優先影格中固定或取消固定玩家？"
L["How do I position Priority Frames?"] = "如何定位優先幀？"
L["How should an Augmentation Evoker use Priority Frames?"] = "增強喚起者應該如何使用優先框架？"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "繼承：此範圍遵循共享光環風格。只有當此範圍需要不同的文字、滑動、邊框或計時器設定時，才啟用自訂光環樣式。"
L["Leave text"] = "留下文字"
L["Live "] = "直播"
L["Live preview is unavailable for this container. Sample mode remains available."] = "此容器無法進行即時預覽。採樣模式仍然可用。"
L["Live preview updates after combat. Sample mode remains available."] = "戰鬥後即時預覽更新。採樣模式仍然可用。"
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "手動固定您想要保持可見的隊友以進行監控或點擊投射。優先框架並不決定誰應該獲得先見之明或黑檀之力。如果您希望繼承的優先框架顯示先見之明、黑檀之力、流沙、起泡鱗片或其他配置的效果，請配置群組框架 > 光環 > 法術指示器。"
L["Native · "] = "母語·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "不要使用連續輪詢或 OnUpdate 循環來進行優先選擇。當配置、引腳、群組狀態或相關單元標識變更需要刷新時，它會解析名冊。自動選擇會讀取魔獸世界分配的坦克角色，並且不會在後台檢查每個小組成員的專業。"
L["No live "] = "沒有直播"
L["No live member"] = "沒有即時會員"
L["No matching aura active"] = "沒有啟動匹配的光環"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "否。自動選擇目前僅使用 WoW 指定的 TANK 角色。治療者、DPS、職業、專長和支持目標必須使用懸停熱鍵手動固定。這避免了背景檢查或輪詢並保持選擇的確定性。"
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "開啟群組框架 > 優先權 > 放置。將條帶附加到活動派對/突襲容器的右側、左側、頂部或底部，或選擇自由位置並在編輯模式下使用專用的優先框架移動器。同一頁控製成長、間距、附件間隙和對齊偏移。"
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "覆蓋活動：此範圍保持其自己的光環風格。在重置覆蓋之前，共用樣式變更不會取代它。"
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "優先框架不會自動偵測其他玩家的專長。自動選擇目前僅支援魔獸世界指定的坦克。使用懸停熱鍵手動固定增強誘發器；優先框架不會選擇理想的預知或黑檀之力目標。"
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "優先框架複製自動坦克並手動將當前組成員固定到穩定的額外條帶中，而無需將其從正常的派對或突襲框架中移除。在一個政黨中，他們繼承政黨框架；在突襲中，他們繼承活躍的突襲或神話突襲框架。他們在派對、突襲和神話突襲中工作，繼承活動的組框架點擊行為，並需要啟用匹配的基礎組框架。"
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "共享光環樣式是單位幀光環文字、滑動、邊框和計時器設定的基線。派對和突襲是具有自己設定的群組框架樣式範圍。"
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "除了派對/Raid 組框架覆蓋之外，紋理是共享的。可依單位或群組範圍自訂漸層。"
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "此組範圍可以使用自訂紋理和漸層。 Raid 也適用於 Mythic Raid。"
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "此範圍可使用自訂漸層和條形設定。紋理仍然遵循共享。"
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "此範圍遵循共用欄設定。當此示波器需要不同的漸變或條形設定時，請在此處開啟自訂設定。"
L["Updates after combat"] = "戰鬥後更新"
L["Where can I request a Priority Frames feature?"] = "我可以在哪裡請求優先幀功能？"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "分組時，在「群組框架」>「優先順序」上設定懸停熱鍵。將滑鼠懸停在 MSUF 派對、Raid 或優先框架上，然後按優先框架熱鍵來固定或取消固定該玩家。無法透過輸入姓名或在目前群組之外新增玩家；已儲存的缺席圖釘會等待並在該玩家重新加入時重新出現。"
L["Why are my Priority Frames empty or missing?"] = "為什麼我的優先框架為空或遺失？"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "是的。包含坦克會自動選擇魔獸世界指定角色為坦克的目前組成員，通常包括您和您的副坦克。要僅顯示您的共同坦克，請停用自動坦克並手動固定其他坦克。如果《魔獸世界》沒有為該玩家指派 TANK 角色，則手動固定是備用方法。"
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "是的。優先框架繼承活動的隊伍、團隊、或神話團隊框架外觀，包括配置的條、文字、光環、狀態指示器和法術指示器。它們使用相同的 MSUF 點擊投射註冊和單元行為，因此現有的點擊投射綁定也適用於重複的影格。"
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "是的。優先框架適用於派對、突襲和神話突襲。在隊伍或地下城中，他們繼承隊伍框架；在突襲中，他們繼承活躍的突襲或神話突襲設置。它們不會創建單獨的條帶，並且必須啟用匹配的基本派對或團隊框架。"
