L["Click a colored element to edit exactly its colors."] = "點擊有顏色的元素以精確編輯它的色彩。"
L["Click an element in the preview to edit its colors. Right-click a color swatch to reset it to default."] = "點擊預覽元素以編輯顏色。右鍵點擊色樣可重設為預設值。"
L["Click to arm this color as a brush, then click a preview element to paint it."] = "點擊將此顏色設為筆刷，然後點擊預覽元素進行上色。"
