L["Right-click to follow the shared castbar text color again."] = "右鍵點擊可重新跟隨共用的施法條文字顏色。"
L["Color for the selected text indicator. Right-click to follow the frame font color again."] = "所選文字指示器的顏色。右鍵點擊可重新跟隨框架的字型顏色。"
L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "施法條文字在取得自己的顏色前會跟隨共用字型設定。"
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "字型樣式跟隨該框架的字型選單；顏色可依指示器單獨設定。"
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "每個施法條文字都可覆蓋共用顏色。目標文字僅存在於目標與專注目標。"
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "單一框架上某個文字指示器的顏色。未設定時指示器會跟隨框架的字型顏色。"
L["Aura Style > Defensive Buffs can follow the frame portrait shape."] = "光環風格 > 防禦增益可跟隨框架肖像的形狀。"
L["Cooldown timer urgency plus shared icon border and shadow colors."] = "冷卻計時器緊急度，以及共用的圖示邊框和陰影顏色。"
