L["Icon Shape"] = "圖示形狀"
L["Keeps Icon Shape synchronized with Aura Style > Shared while the remaining Group Aura settings stay local."] = "使圖示形狀與光環風格 > 共用保持同步，其餘團隊光環設定仍為獨立設定。"
L["Shared icon shape"] = "共用圖示形狀"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "可見性模式僅適用於單位和團隊框架。光環提示使用各自的顯示滑鼠提示開關，即使選擇從來沒有也不會覆蓋它們。光環只會沿用所選的 Blizzard/MSUF 外觀和游標位置。"
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "套用於整個施法條：條、圖示、所有文字、效果和邊框。所有 MSUF 元素共用這個 0-30 順序；層級 30 的任何部分都繪製在層級 29 的任何部分之上。"
L["Display: "] = "顯示："
L["Enemy debuffs: hide only exact noisy SpellIDs. Selected Dots on target are handled automatically by that scope's Auto-blacklist toggle."] = "敵方減益：僅隱藏確切的干擾 SpellID。所選的目標 DoT 由該範圍的自動黑名單開關自動處理。"
