--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "永遠隱藏"
L["Blizzard Raid Manager"] = "暴雪突襲管理器"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "螢幕左邊緣的暴雪頁籤，包含準備確認、突襲標記與職責篩選。它是唯一的共用框架，因此此設定對隊伍、突襲與神話突襲完全相同。"
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "淡出突襲管理器，直到滑鼠碰到它。準備確認、突襲標記與職責篩選仍可使用，展開的面板會持續顯示，直到你再次將其收合。"
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "始終讓突襲管理器保持不可見且不攜截點擊。切換回其他選項即可重新使用它的按鈕。"
L["Show on mouseover"] = "滑鼠移過時顯示"
L["Automatic"] = "自動"
L["Always visible"] = "永遠顯示"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "當 MSUF 提供目前的隊伍框架時隱藏突襲管理器，其餘情況交給魔獸世界處理。MSUF 一直都是這樣運作的。"
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "即使啟用了 MSUF 隊伍框架，也保持突襲管理器可用。如果你仍需要它的準備確認、突襲標記與職責篩選，就選這個。"
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "由隊伍、突襲與神話突襲共用。「自動」會在 MSUF 提供隊伍框架時隱藏該頁籤。"
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "偵測到 %s：全域錨點會跟隨重要冷卻管理器。可在 MSUF 編輯模式中用 Cooldown 將其關閉。"
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "偵測到 %s：冷卻管理器錨定已關閉。可在 MSUF 編輯模式中用 Cooldown 將其開啟。"
L["Cooldown Manager anchoring (%s)"] = "冷卻管理器錨定（%s）"
L["Global anchor (%s Anchor)"] = "全域錨點（%s 錨點）"
L["Fades all four outer edges; 0% keeps the original texture."] = "淡化四個外緣；0% 保留原始材質。"

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 顯示已設定的光環像素大小。"
L["Aura Options"] = "光環選項"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "光環選項與光環樣式屬於此 UnitFrame。全域圖示外觀：外觀 > 光環樣式。"
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "低於此數值時，剩餘時間可顯示一位小數。設為 0 則只顯示整秒。"
L["Buff Appearance"] = "增益外觀"
L["Debuff Appearance"] = "減益外觀"
L["Global Aura Appearance: Buffs"] = "全域光環外觀：增益"
L["Global Aura Appearance: Debuffs"] = "全域光環外觀：減益"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "計時器顏色由即時單位/隊伍光環與所有預覽共用。圖示邊框與陰影顏色位於外觀 > 光環中，並依光環類型分別設定。"
L["Click to open the setting that enables this layer."] = "點擊以開啟啟用該圖層的設定。"
L["Controls native Aura tooltips for Spell Icons only."] = "僅控制法術圖示的原生光環工具提示。"
L["Cooldown text format"] = "冷卻文字格式"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "複製增益、減益效果、外部防禦效果與法術圖示的顯示方式，包含圖示縮放、文字、掃描、持續時間條與排序。光環選項、已追蹤的法術圖示以及全域外觀主題維持不變。"
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "複製小隊光環的顯示、版面配置、過濾器、精確與分類黑名單、框架層級與驅散選項。光環樣式與全域外觀主題維持不變。"
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "複製此 UnitFrame 的光環顯示、版面配置、過濾器、黑名單、自訂光環設定與追蹤法術。光環樣式與全域外觀主題維持不變。"
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "複製此 UnitFrame 的增益、減益效果、自訂光環、玩家防禦效果與目標 DoT 的顯示方式，包含文字、掃描、圖示縮放、持續時間條、臨期提醒與整框特效。光環選項與全域外觀主題維持不變。"
L["Drag background (%dx)"] = "拖曳背景 (%dx)"
L["Drag to move. Arrow keys nudge."] = "拖曳以移動。方向鍵可微調。"
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "EllesmereUI 解鎖模式"
L["Exact X coordinate"] = "精確 X 座標"
L["Exact Y coordinate"] = "精確 Y 座標"
L["Fit shows the complete aura layout."] = "符合顯示完整的光環版面配置。"
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "全域外觀主題僅依光環類型選擇。版面配置、過濾器、計時器、文字與特效仍在對應的 UnitFrame 或 GroupFrame 中依作用範圍生效。"
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "個別樣式在此編輯。共用圖示主題：外觀 > 光環樣式。"
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "版面配置、過濾器、清單以及每個容器專屬的樣式都保存在各自的框架中。外觀 > 光環樣式僅管理全域圖示主題。"
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "以預覽框架的中心為基準測量。正值向右移動。方向鍵與拖曳更新的是同一個位置。"
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "以預覽框架的中心為基準測量。正值向上移動。方向鍵與拖曳更新的是同一個位置。"
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "開啟（預設）：MSUF 框架會出現在 EllesmereUI 解鎖模式中。關閉後可繼續使用 MSUF 內建的編輯模式。MSUF 設定檔中的位置始終為準。"
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "開啟框架並展開光環。增益與減益效果擁有各自的版面配置、過濾器、黑名單與樣式；自訂 1-3、防禦增益與目標 DoT 則提供符合其內容的選項。"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "開啟全域光環圖示主題：邊框、陰影、顏色、行距以及原生的玩家武器附魔。此 GroupFrame 的個別樣式仍保留在這裡。"
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "效能警告 (12.1)：只要光環存在已計算的臨期時間視窗，暴雪就可能對每個可見的光環按鈕逐幀執行 OnUpdate，而不只是在顯示警告時。僅在你接受戰鬥中這項潛在高負擔時才啟用。"
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "在實際的 GroupFrames 上塗上暫代色調，方便在沒有真實可驅散減益效果時判斷覆蓋效果。關閉此頁面時會自動停用。"
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "在實際的 UnitFrame 上塗上暫代色調，方便在沒有真實可驅散減益效果時判斷覆蓋效果。關閉此頁面時會自動停用。"
L["Position is controlled by the colored aura handle in Preview."] = "位置由預覽中帶顏色的光環控制點控制。"
L["Preview position"] = "預覽位置"
L["Runtime Preview"] = "即時預覽"
L["Runtime Preview: live GroupFrames"] = "即時預覽：實際的 GroupFrames"
L["Runtime Preview: live UnitFrame"] = "即時預覽：實際的 UnitFrame"
L["Runtime Preview: live UnitFrame (drag)"] = "即時預覽：實際的 UnitFrame（拖曳）"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "形狀、邊框與陰影：外觀 > 光環樣式 > 增益。此處所有選項仍依小隊作用範圍生效。"
L["Shared Aura Style"] = "共用光環樣式"
L["Shared Aura Style: Buffs"] = "共用光環樣式：增益"
L["Shared Aura Style: Debuffs"] = "共用光環樣式：減益效果"
L["Shared Preview - "] = "共用預覽 - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "在實際的 UnitFrame 上顯示暫代符號，讓你無需真實減益效果即可將其拖到定位。關閉此頁面時會自動停用。"
L["Spell Icon Style"] = "法術圖示樣式"
L["Spell Icon tooltip"] = "法術圖示工具提示"
L["Swipe Direction"] = "掃描方向"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "此開關僅在載入 EllesmereUI 時顯示。關閉後 MSUF 會立即返回內建的編輯模式。"
L["Use - / + or Ctrl + mouse wheel to zoom."] = "使用 - / + 或 Ctrl + 滑鼠滾輪進行縮放。"
L["Use EllesmereUI Unlock Mode for MSUF"] = "為 MSUF 使用 EllesmereUI 解鎖模式"
L["Use the colored Texture handle in Preview for exact placement."] = "使用預覽中帶顏色的材質控制點進行精確定位。"
L["Zoom changes only this preview, not your Aura settings."] = "縮放只影響此預覽，不會變更你的光環設定。"

-- Menu localization pass 2026-08-06 (part 2): dropdown values, tooltips and labels routed through Tr() that the coverage extractor could not see.
L["+ Value"] = "+ 數值"
L["1 px"] = "1 px"
L["12.1 Pandemic state"] = "12.1 臨期狀態"
L["2 px"] = "2 px"
L["Absorb (negative)"] = "吸收（負值）"
L["Absorb (positive)"] = "吸收（正值）"
L["Add enemy debuff"] = "新增敵方減益效果"
L["Add entire set"] = "新增整個合集"
L["Add spell"] = "新增法術"
L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "將暴雪的暫時武器附魔按鈕加入玩家增益容器。這是一項共用設定，使用原生光環流程，不含 MSUF 計時器或 OnUpdate。"
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "新增精選清單中缺少的精確有害光環 ID。該光環仍限於你目前的目標以及由你施放的光環。"
L["Adds one exact buff to this frame's blacklist."] = "將一個精確的增益加入此框架的黑名單。"
L["Adds one exact buff to this group's blacklist."] = "將一個精確的增益加入此小隊的黑名單。"
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "將一個精確的有害光環加入此目標、專注或首領黑名單。僅當無法協助該單位時，暴雪才會套用任意的 SpellID 過濾。"
L["All Buffs"] = "所有增益"
L["All Debuffs"] = "所有減益效果"
L["All roles"] = "所有職責"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "一律排除沒有持續時間的光環，即使暴雪標記過濾器已關閉。"
L["Always excludes auras without a duration."] = "一律排除沒有持續時間的光環。"
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "一律排除沒有持續時間的光環。標記過濾器關閉時仍然有效。"
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "一律排除沒有持續時間的光環。此原生規則優先於 SpellID 黑名單與白名單。"
L["Anchor To Class Resource"] = "錨定至職業資源"
L["Any Dispel Type"] = "任意驅散類型"
L["Any dispel type"] = "任意驅散類型"
L["Applicable by Me (Raid)"] = "我可施加（團隊）"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "適用於此光環類型的所有 UnitFrame 與 GroupFrame 圖示。法術圖示使用增益外觀。"
L["Aura sort order"] = "光環排序順序"
L["Aura sorting"] = "光環排序"
L["Aura tooltip"] = "光環工具提示"
L["Auto breakpoints"] = "自動斷點"
L["Auto fit"] = "自動符合"
L["Auto fit pips"] = "自動符合格數"
L["Auto-blacklist from Debuffs"] = "自動從減益效果中排除"
L["Auto-blacklist from player buffs"] = "自動從玩家增益中排除"
L["Auto: Essential Cooldowns"] = "自動：核心冷卻"
L["Auto: Unit Frame"] = "自動：單位框架"
L["Auto: Utility Cooldowns"] = "自動：輔助冷卻"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "僅條會隱藏光環圖示。圖示 + 條則保留圖示並在其上繪製持續時間條。"
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "條維持一般狀態條。跟隨玩家資源會沿用獨立分離的玩家資源形狀。寶珠使用單一的垂直填充。"
L["Big Defensive"] = "強力防禦"
L["Big Defensive Player"] = "強力防禦（玩家）"
L["Blizzard castbar"] = "暴雪施法條"
L["Blizzard ring + symbol"] = "暴雪光環 + 符號"
L["Blizzard symbol"] = "暴雪符號"
L["Blocks every aura in the selected curated MSUF set."] = "封鎖所選 MSUF 精選合集中的所有光環。"
L["Blocks only the selected aura from the curated set."] = "僅封鎖精選合集中所選的那個光環。"
L["Cancelable Player"] = "可取消（玩家）"
L["Castbar Border"] = "施法條邊框"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "僅變更分離的玩家資源條。左側的職業資源形狀只變更職業資源。"
L["Class Resource Preview"] = "職業資源預覽"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "職業資源與玩家資源沿用現有框架。自訂使用下方滑桿。寬度僅在版面配置更新時決定。"
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "僅控制第二條生命條的輪廓。條使用四條外邊框；形狀則使用其固定的邊緣材質。0 只會關閉輪廓。"
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "僅控制這條第二生命條。一般玩家框架的生命文字仍然獨立。"
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "獨立控制此光環列。全域樣式 > 雜項下的一律 / 脫離戰鬥 / 輔助鍵 / 永不僅影響單位框架與小隊框架。光環只沿用所選的暴雪/MSUF 外觀與游標位置。"
L["Cooldown swipe direction"] = "冷卻掃描方向"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "核心功能，對新設定檔預設啟用，對既有設定檔啟用一次。即使未啟用頭像，它也可作為一般的防禦增益條使用。關閉後將同時停用條與頭像位置顯示。"
L["Crowd Control"] = "控場效果"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "為正式服 12.0+ 與 12.1 精選的 DoT 光環。追蹤僅限於此 UnitFrame 的單位以及由你施放的光環；首領設定分別繫結 boss1 至 boss5。"
L["Custom Spell ID"] = "自訂法術 ID"
L["Dark Border"] = "深色邊框"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "預設關閉。只要光環存在已計算的臨期時間視窗，暴雪的原生實作就會為每個可見的光環按鈕啟用逐幀 OnUpdate；這可能在警告顯示之前就已開始。"
L["Dispellable by Group"] = "小隊可驅散"
L["Dispellable by Me (Raid)"] = "我可驅散（團隊）"
L["Dispellable by group"] = "小隊可驅散"
L["Down (Single Column)"] = "向下（單欄）"
L["Duration bar display"] = "持續時間條顯示方式"
L["Duration bar fill mode"] = "持續時間條填充模式"
L["Duration bar position"] = "持續時間條位置"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "所有分離玩家資源形狀的邊緣強度，包含條、圓形、水晶與寶珠。0 只會關閉該邊緣。"
L["Elapsed / Total"] = "已過 / 總計"
L["Enable defensive buffs"] = "啟用防禦增益"
L["Enable tracked DoTs"] = "啟用追蹤 DoT"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "輸入法術 ID、貼上法術連結或鍵入法術名稱。即使增益 ID 與施放的法術 ID 不同，也能辨識出可見的有益光環。"
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "輸入法術 ID、貼上法術連結或鍵入法術名稱。此白名單追蹤精確的法術 ID。"
L["Essential cooldown viewer"] = "核心冷卻檢視器"
L["Exact aura tracking"] = "精確光環追蹤"
L["External Defensive"] = "外部防禦"
L["External Defensive Player"] = "外部防禦（玩家）"
L["Fill Mode"] = "填充模式"
L["Focus off"] = "專注關閉"
L["Focus on"] = "專注開啟"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global 沿用 MSUF 一般的生命顏色模式。Class Color 強制使用你的職業顏色。Dark Mode 強制使用已設定的深色條顏色。HP Gradient 僅依目前生命值為這條第二生命條著色。"
L["Global icon shape"] = "全域圖示形狀"
L["HP Color"] = "生命顏色"
L["HP Outline"] = "生命輪廓"
L["HP Shape"] = "生命條形狀"
L["HP only"] = "僅生命"
L["Healers only"] = "僅治療"
L["Hide permanent auras"] = "隱藏永久光環"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "在目標 DoT 啟用期間，將此作用範圍所選的 DoT 法術 ID 從同一 UnitFrame 的一般減益容器中隱藏。暴雪的黑名單以 SpellID 為準，因此其他玩家施放的同一法術也會一併隱藏。"
L["Highest priority only"] = "僅最高優先度"
L["Icon Border & Shadow"] = "圖示邊框與陰影"
L["Include Nameplate-only"] = "包含僅名條"
L["Inside Left"] = "內側左"
L["Inside Right"] = "內側右"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "讓分離的玩家資源保持附著於職業資源條。此連線啟用時，玩家資源的選項將被停用。"
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "將已設定的頭像尺寸與位置保留為隱形錨點，使防禦圖示能在頭像本身關閉時仍留在該處。"
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "將已設定的頭像尺寸、位置與形狀保留為隱形錨點，供追蹤 DoT 在頭像本身關閉時使用。"
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "將頭像處同時顯示的 DoT 圖示限制為 1 至 8 個。多出的圖示會依此 DoT 列所設的成長方向向外排列。"
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "將頭像處同時顯示的防禦圖示數量限制為 1 至 8 個。既有設定檔在變更此數值前將維持為 1。"
L["Lists every MSUF slash command in chat, diagnostics included."] = "在聊天視窗中列出所有 MSUF 斜線指令，包含診斷指令。"
L["Max portrait icons"] = "頭像圖示上限"
L["Maximum debuff duration"] = "最長減益持續時間"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "同時移動分離玩家資源的所有文字欄位。下方的欄位 X/Y 選項可加入各自的偏移。"
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "將玩家資源條移出單位框架。錨定會將其連接到職業資源堆疊；同步則只跟隨堆疊的寬度。"
L["Native Aura Flow"] = "原生光環流程"
L["Blizzard Buff & Debuff Frames"] = "暴雪增益與減益框架"
L["Hide Blizzard Buff and Debuff Frames"] = "隱藏暴雪增益與減益框架"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "僅隱藏小地圖附近的暴雪玩家增益框架與一般減益圖示。私密光環與致命減益警告仍會顯示。"
L["Buffs hidden"] = "增益已隱藏"
L["Buffs visible"] = "增益可見"
L["Debuffs hidden"] = "減益已隱藏"
L["Debuffs visible"] = "減益可見"
L["Hide Blizzard Buff Frame"] = "隱藏暴雪增益框架"
L["Hide Blizzard Debuff Frame"] = "隱藏暴雪減益框架"
L["Hides Blizzard's player Buff Frame near the minimap."] = "隱藏小地圖附近的暴雪玩家增益框架。"
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "僅隱藏小地圖附近的暴雪一般減益圖示。私密光環與致命減益警告仍會顯示。"
L["Native size"] = "原生尺寸"
L["Native stealable marker"] = "原生可偷取標記"
L["Native weapon enchant auras"] = "原生武器附魔光環"
L["No roles"] = "無職責"
L["No width limit"] = "無寬度限制"
L["Not Cancelable"] = "不可取消"
L["Not Cancelable Player"] = "不可取消（玩家）"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "關閉時顯示任意持續時間的減益效果。否則將隱藏總持續時間超過該秒數的減益效果。"
L["One per dispel type"] = "每種驅散類型一個"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "開啟全域光環圖示主題：邊框、陰影、顏色、行距以及原生的玩家武器附魔。此框架的容器樣式仍保留在這裡。"
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "為這條第二生命條提供選用的內插。關閉時維持直接的原生 SetValue 更新。"
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "選用的呈現方式；防禦增益功能本身並不需要頭像。啟用頭像時，第一個圖示會佔據頭像。頭像關閉時，請啟用下方的位置選項以將圖示保留在該處；否則 MSUF 會安全地回復為一般防禦條。"
L["Orb Size"] = "寶珠大小"
L["Pandemic Warning & Style"] = "臨期警告與樣式"
L["Pandemic color"] = "臨期顏色"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "將玩家資源文字放置在分離的資源條上。關閉時，同一文字仍依一般文字版面配置定位。"
L["Places the duration bar at the top or bottom edge of the aura slot."] = "將持續時間條放置在光環欄位的上緣或下緣。"
L["Player Text Outline"] = "玩家文字輪廓"
L["Power Bar Outline"] = "資源條輪廓"
L["Power Text On Bar"] = "條上的資源文字"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "資源錨點在玩家資源條可見時使用它；否則生命條將回復為職業資源錨點。"
L["Raid In Combat"] = "團隊戰鬥中"
L["Raid In Combat Player"] = "團隊戰鬥中（玩家）"
L["Raid Player"] = "團隊（玩家）"
L["Remaining / Total"] = "剩餘 / 總計"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "剩餘會隨著光環到期而縮短。已過則會持續增加直到光環到期。"
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "低於此數值時，剩餘時間會使用一位小數。計時器在不足 1 分鐘時顯示不帶單位的秒數，超過時顯示在地化的分鐘。設為 0 則只顯示整秒。"
L["Remove from blacklist"] = "從黑名單移除"
L["Remove from whitelist"] = "從白名單移除"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "繪製第二條原生的玩家生命條。一般玩家框架的生命條不受影響，因此你可以顯示兩次生命值。"
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "以頭像大小的圖示取代一般 DoT 列。第一個圖示會完全沿用此框架頭像的寬度、高度與形狀。"
L["Runs /msuf reset for frame positions and visibility."] = "對框架位置與顯示狀態執行 /msuf reset。"
L["Second Player HP Bar"] = "第二條玩家生命條"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "設定分離資源文字所使用的玩家字型作用範圍。玩家名稱與生命文字共用此輪廓設定。"
L["Show DoTs at portrait position"] = "在頭像位置顯示 DoT"
L["Show buffs at portrait position"] = "在頭像位置顯示增益"
L["Show cooldown text on portrait"] = "在頭像上顯示冷卻文字"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "在頭像圖示上顯示目前防禦增益的剩餘持續時間。暴雪會以原生方式更新該文字。"
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "在下方顯示所選職業/專精的資源，不會變更你的角色、專精或已儲存的設定。"
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "在頭像圖示上顯示所追蹤 DoT 的剩餘持續時間。暴雪會以原生方式更新該持續時間。"
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "當分離資源由職業資源管理時，可用於玩家資源文字的簡單預設。自訂欄位表示在你選擇預設之前將保留現有的欄位版面配置。"
L["Smooth Fill"] = "平滑填充"
L["Spell Text"] = "法術文字"
L["Stops blocking this aura."] = "停止封鎖此光環。"
L["Sync Width"] = "同步寬度"
L["Tanks only"] = "僅坦克"
L["Target DoT"] = "目標 DoT"
L["Target off"] = "目標關閉"
L["Target on"] = "目標開啟"
L["Time Text"] = "時間文字"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "追蹤此預設的防禦增益。該設定同時適用於防禦條與選用的頭像圖示。"
L["Tracked buffs viewer"] = "追蹤增益檢視器"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "在此 UnitFrame 的單位上追蹤你所選的有害光環。首領框架使用各自的 boss1 至 boss5 單位識別碼。"
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "為此框架開啟或關閉暴雪標記過濾器。首次變更會自動建立框架專屬規則；已移轉的共用規則在編輯前仍維持共用。"
L["Unavailable cast fill"] = "無法使用的施法填充"
L["Up (Single Column)"] = "向上（單欄）"
L["Use Player HP Text"] = "使用玩家生命文字"
L["Use portrait position while portrait is off"] = "頭像關閉時使用頭像位置"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "僅當此生命條明確設為寶珠時才會使用。跟隨玩家資源則改為繼承玩家資源的寶珠大小。"
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "使用暴雪 12.1 AuraButton 的可偷取過濾器。不會新增任何 MSUF 光環掃描、計時器或 OnUpdate。"
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "使用玩家生命文字設定，並在已繪製的玩家生命文字為最新時直接複製。區域文字 X/Y 仍屬於此條。"
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "為分離的玩家資源使用職業資源的寬度，同時不讓職業資源接管玩家資源的選項。"
L["Utility cooldown viewer"] = "輔助冷卻檢視器"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "位於已填充生命值的後方。生命值為 100% 時填充會覆蓋背景；輪廓設為 0 也不會關閉此材質。"
L["Weapon Enchants Off"] = "武器附魔關閉"
L["Weapon Enchants On"] = "武器附魔開啟"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "只要防禦條或頭像圖示處於啟用狀態，就會將所有已啟用的追蹤防禦從玩家的一般增益列中隱藏。已停用的防禦項目仍會顯示在那裡。"
L["Whole frame"] = "整個框架"
L["Width Mode"] = "寬度模式"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "狀態條背景色調 深色模式自訂顏色 背景 底紋 bg 不透明度 alpha background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "框架基礎 啟用 載入條件 透明度 距離淡出 玩家 目標 專注 寵物 消失 不可見"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "框架基礎 平滑填充 資源條 平滑填充 生命動畫 資源動畫 smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "一般 使用 MSUF 小隊框架 若此開關關閉 啟用 停用 關閉 隱藏 團隊 小隊 史詩"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "小隊/團隊框架 版面配置 生命平滑填充 生命文字 資源條 平滑填充 小隊 團隊 smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "小隊/團隊框架 版面配置 透明度 不透明度 淡出 目標 戰鬥中 脫離戰鬥 alpha 整個框架 狀態條 生命 背景 生命填充 生命軌道 保留生命顏色"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "MSUF 編輯模式可移動框架與支援的施法條。光環圖示的位置在各單位頁面 > 光環或小隊/團隊框架 > 光環中設定。"
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "雜項 全域樣式 語言 選單行為 啟動提示 工具提示 暴雪框架 小地圖 音效"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "姓名縮寫 為此作用範圍使用自訂設定 覆寫 小隊 團隊 小隊框架姓名截斷 字型覆寫 共用變更"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "開啟外觀 > 光環，設定依作用範圍生效的冷卻文字、層數文字、掃描與持續時間條樣式。計時器顏色仍位於顏色 > 光環。"
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "開啟首領框架 > 光環 > 減益效果。SpellID 黑名單項目、暴雪過濾器、位置與預覽都集中在那裡；樣式仍位於外觀 > 光環。"
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "開啟全域樣式 > 雜項 > 單位框架工具提示，以控制 MSUF 單位框架與小隊框架工具提示的來源、錨點、顯示模式與輔助鍵。"
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "開啟全域樣式 > 雜項，設定語言、選單行為、啟動提示、工具提示、暴雪框架、小地圖圖示與音效。"
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "開啟小隊/團隊框架 > 版面配置 > 距離淡出。影響對象可選擇淡出框架或生命值，alpha 滑桿則控制超出距離與離線時的不透明度。"
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "開啟小隊/團隊框架 > 版面配置 > 透明度。不透明度控制戰鬥中與脫離戰鬥的 alpha；淡出目標可選擇整個框架、狀態條、生命值或背景。背景與生命圖層設定基礎顏色、生命填充與生命軌道的不透明度。"
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "開啟小隊/團隊框架 > 版面配置中的生命平滑填充。若要設定小隊框架的資源條，請開啟小隊/團隊框架 > 版面配置 > 資源欄 > 平滑填充。"
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "開啟小隊/團隊框架 > 版面配置，在頂部選擇小隊、團隊或史詩，然後關閉使用 MSUF 小隊框架。透過若此開關關閉可選擇暴雪框架是正常顯示，還是兩套框架系統都保持隱藏。"
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "開啟小隊/團隊框架 > 版面配置。框架基礎與排序控制玩家與自身的顯示，以及玩家單位在小隊框架中的排列順序。"
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "開啟小隊/團隊框架 > 版面配置。框架基礎/版面配置控制寬度、高度、間距、欄數與成長方向；影格縮放控制縮放行為。"
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "開啟小隊/團隊框架 > 狀態和指標，設定狀態圖示、職責/隊長/助理、備戰確認、專注光效以及其他小隊框架狀態指示。"
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "開啟玩家 > 光環，然後關閉該玩家框架的增益。依作用範圍生效的文字與冷卻樣式仍位於外觀 > 光環。"
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "開啟某個單位頁面，然後使用距離淡出。它適用於目標、目標的目標、專注、專注的目標、寵物與首領。"
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "開啟受影響的 UnitFrame > 光環，設定圖示大小、位置與過濾器。依作用範圍生效的文字與冷卻樣式請使用外觀 > 光環。"
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "開啟受影響的 UnitFrame > 光環或小隊/團隊框架 > 光環，減少可見數量、計時器文字或不必要的原生過濾規則。"
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "開啟受影響的 UnitFrame > 光環，選擇增益或減益效果，然後調整過濾器、圖示大小、列數、上限與間距。小隊/團隊的設定位於小隊/團隊框架 > 光環。"
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "開啟單位頁面 > 光環或光環位置彈出視窗來放置單位框架的光環。增益/減益圖示屬於光環版面配置設定，不透過 MSUF 編輯模式移動。"
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "距離淡出 小隊框架 距離偵測 團隊距離偵測 小隊距離偵測 超出距離 alpha 離線不透明度 影響 框架 生命"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "距離淡出 單位框架 距離偵測 距離檢查 超出距離 距離 alpha 距離淡出 目標 目標的目標 專注 專注的目標 寵物 首領"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "圓角材質 圓角框架材質 單位框架 小隊框架 資源條 滑鼠停留高亮 圓角框架 圓角"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "狀態圖示 指示器 等級 已啟用 附著點 X 偏移 Y 偏移 大小 圖層 等級文字 等級指示 玩家等級 目標等級"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "文字 附著點 偏移 字型大小 圖層 繪製順序 間距 分離間距 重疊 狀態條 肖像 狀態圖示"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "使用小隊/團隊框架 > 版面配置設定框架大小與間距，使用光環設定增益/減益的位置，使用狀態和指標設定固定位置的狀態圖示。"
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "使用小隊/團隊框架的各個頁面：版面配置設定大小、成長、排序、狀態條與文字；光環設定增益/減益的位置；狀態和指標設定狀態圖示。"
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "使用單位頁面設定各單位的施法條開關，使用全域樣式 > 施法條設定共用的材質、方向、文字與中斷選項。"
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "歡迎使用職業資源！\n\n是否自動設定一條分離的職業條，\n並將其放置在你的核心冷卻上方？\n\n此操作將一鍵設定職業資源的顯示、\n錨定、寬度比對以及分離的玩家資源。\n\n你之後隨時可以透過下方的\n|cff00ff00快速設定：職業條|r 按鈕再次執行。"
