-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "確認錨定"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "只有當你希望整個單位框架版面配置隨冷卻一起移動時才確認。"
L["Keep independent"] = "保持獨立"
L["MSUF detected %s."] = "MSUF 偵測到 %s。"
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF 現在會將全域單位框架版面配置錨定到 Essential Cooldown Manager。"
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "在下一步再次確認之前不會移動任何內容。若選擇保持獨立，你隨時可以在 MSUF 編輯模式或 MSUF 選單的單位 > 錨定中啟用 CDM 錨定。"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "在下一步再次確認之前不會移動任何內容。你稍後可以在 MSUF 編輯模式中變更。"
